# 2. 舵机角和阿克曼角换算
def ackermann_to_servo(angle_deg, chassis):
    """把等效阿克曼角换算为舵机角。"""
    if abs(angle_deg) > chassis.max_ackermann_angle_deg:
        raise ValueError("阿克曼角超过底盘限幅")
    if angle_deg >= 0.0:
        span = chassis.servo_max_deg - chassis.servo_center_deg
    else:
        span = chassis.servo_center_deg - chassis.servo_min_deg
    return chassis.servo_center_deg + (
        chassis.servo_direction
        * angle_deg
        / chassis.max_ackermann_angle_deg
        * span
    )


def servo_to_ackermann(servo_deg, chassis):
    """把舵机角换算为等效阿克曼角。"""
    offset = (servo_deg - chassis.servo_center_deg) * chassis.servo_direction
    if offset >= 0.0:
        span = chassis.servo_max_deg - chassis.servo_center_deg
    else:
        span = chassis.servo_center_deg - chassis.servo_min_deg
    return offset / span * chassis.max_ackermann_angle_deg

